import { Title } from "@solidjs/meta";
import { createAsync, useAction, useSubmission } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import {
  readContact,
  validateContact,
  type ContactErrors,
  type ContactResult,
  type ContactValues
} from "~/lib/contact";
import { getPostedContact, sendContact } from "~/lib/contact.server-fns";

export default function Contact() {
  // Result of a no-JavaScript POST to /contact, rendered by the server.
  const posted = createAsync(() => getPostedContact());
  const [local, setLocal] = createSignal<ContactResult>();
  const send = useAction(sendContact);
  const submission = useSubmission(sendContact);

  const result = () => local() ?? posted() ?? undefined;
  const values = (): ContactValues => result()?.values ?? { name: "", email: "", message: "" };
  const errors = (): ContactErrors => result()?.errors ?? {};

  const onSubmit = async (event: SubmitEvent) => {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const data = new FormData(form);
    const entered = readContact(data);
    const found = validateContact(entered);
    if (Object.keys(found).length) {
      setLocal({ values: entered, errors: found });
      return;
    }
    setLocal({ values: entered, errors: {} });
    try {
      setLocal(await send(data));
    } catch {
      setLocal({ values: entered, errors: {} });
    }
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={result()?.success}>
        {message => (
          <p class="success" role="status">
            {message()}
          </p>
        )}
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit} class="contact-form">
        <div class="field">
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={values().name}
            aria-invalid={errors().name ? "true" : undefined}
            aria-describedby={errors().name ? "contact-name-error" : undefined}
          />
          <Show when={errors().name}>
            {error => (
              <p class="error" id="contact-name-error">
                {error()}
              </p>
            )}
          </Show>
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={values().email}
            aria-invalid={errors().email ? "true" : undefined}
            aria-describedby={errors().email ? "contact-email-error" : undefined}
          />
          <Show when={errors().email}>
            {error => (
              <p class="error" id="contact-email-error">
                {error()}
              </p>
            )}
          </Show>
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={6}
            value={values().message}
            aria-invalid={errors().message ? "true" : undefined}
            aria-describedby={errors().message ? "contact-message-error" : undefined}
          />
          <Show when={errors().message}>
            {error => (
              <p class="error" id="contact-message-error">
                {error()}
              </p>
            )}
          </Show>
        </div>
        <button type="submit" disabled={submission.pending}>
          Send
        </button>
      </form>
    </>
  );
}
EOF
