import { Title } from "@solidjs/meta";
import { createAsync, type RouteDefinition } from "@solidjs/router";
import { createSignal, For, onMount, Show } from "solid-js";
import { getBooks } from "~/lib/books";
import { isFavorite, loadFavorites } from "~/lib/favorites";

export const route = {
  preload: () => getBooks()
} satisfies RouteDefinition;

export default function Books() {
  const books = createAsync(() => getBooks());
  const [selected, setSelected] = createSignal<string | null>(null);
  onMount(loadFavorites);

  const tags = () =>
    [...new Set((books() ?? []).flatMap(book => book.tags))].sort((a, b) =>
      a.localeCompare(b, "en")
    );
  const visible = () => {
    const tag = selected();
    return (books() ?? []).filter(book => tag === null || book.tags.includes(tag));
  };

  return (
    <>
      <Title>Books | Bookshelf</Title>
      <h1>All books</h1>
      <div class="tag-filter" role="group" aria-label="Filter by tag">
        <button
          type="button"
          aria-pressed={selected() === null ? "true" : "false"}
          onClick={() => setSelected(null)}
        >
          All
        </button>
        <For each={tags()}>
          {tag => (
            <button
              type="button"
              aria-pressed={selected() === tag ? "true" : "false"}
              onClick={() => setSelected(tag)}
            >
              {tag}
            </button>
          )}
        </For>
      </div>
      <ul aria-label="Books" class="book-list">
        <For each={visible()}>
          {book => (
            <li>
              <a href={`/books/${book.slug}`}>{book.title}</a>{" "}
              <span class="meta">
                {book.author}, {book.year}
              </span>
              <Show when={isFavorite(book.slug)}>
                {" "}
                <span class="favorite">Favorite</span>
              </Show>
            </li>
          )}
        </For>
      </ul>
    </>
  );
}
