cat > 'src/routes/books/[slug].tsx' <<'EOF'
import { Title } from "@solidjs/meta";
import { createAsync, useParams, type RouteDefinition } from "@solidjs/router";
import { For, onMount, Show } from "solid-js";
import NotFound from "~/components/NotFound";
import { getBook } from "~/lib/books";
import { isFavorite, loadFavorites, toggleFavorite } from "~/lib/favorites";

export const route = {
  preload: ({ params }) => getBook(params.slug!)
} satisfies RouteDefinition;

export default function BookPage() {
  const params = useParams<{ slug: string }>();
  const book = createAsync(() => getBook(params.slug));
  onMount(loadFavorites);

  return (
    <Show when={book() !== undefined}>
      <Show when={book()} fallback={<NotFound />}>
        {book => (
          <article>
            <Title>{`${book().title} | Bookshelf`}</Title>
            <h1>{book().title}</h1>
            <p class="author">by {book().author}</p>
            <p>Published in {book().year}</p>
            <p>Rating: {book().rating}/5</p>
            <ul class="tags" aria-label="Tags">
              <For each={book().tags}>
                {tag => (
                  <li>
                    <a href="/books">{tag}</a>
                  </li>
                )}
              </For>
            </ul>
            <button type="button" onClick={() => toggleFavorite(book().slug)}>
              {isFavorite(book().slug) ? "Remove from favorites" : "Add to favorites"}
            </button>
            <div class="body" innerHTML={book().html} />
          </article>
        )}
      </Show>
    </Show>
  );
}
